/// <summary>
///     The <c>AVADirPersonDbt_Extension</c> class is the extension for <c>DirPerson</c>
/// </summary>
[ExtensionOf(tableStr(DirPerson))]
final class AVADirPersonDbt_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(DirPerson, PersonalTitle):
            this.avaUpdatePersonalTitleFields();
            break;

        default:
            break;
    }
}

/// <summary>
///    AVA <c>avaUpdatePersonalTitleFields</c> method.
/// </summary>
public void avaUpdatePersonalTitleFields()
{
    DirNameAffix locDirNameAffix;

    locDirNameAffix     = DirNameAffix::findRecId(this.PersonalTitle);

    if(locDirNameAffix.RecId)
    {
        this.Gender     = locDirNameAffix.AVAGender;
        this.KnownAs    = locDirNameAffix.AVAKnownAs;
    }
}

/// <summary>
///     AVA <c>avaUpdatePersonalTitleFields</c> method.
///     returns name with connected title
/// </summary>
/// <param name="_languageId">
///     <c>LanguageId</c> as type
/// </param>
/// <param name="_lastNameFirst">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>AVAContactName</c> as return value
/// </returns>
public AVAContactName avaGetNameWithTitle(  LanguageId  _languageId     = CompanyInfo::find().LanguageId,
                                            boolean     _lastNameFirst  = false                             )
{
    AVAContactName              retVal;

    AVAContactName              locAVAContactName;

    DirPersonName               locDirPersonName;
    DirNameAffix                locDirNameAffix;
    AVADirNameAffixTranslation  locAVADirNameAffixTranslation;

    locDirPersonName                = DirPersonName::find(this.RecId);
    if(this.PersonalTitle)
    {
        locDirNameAffix                 = DirNameAffix::findRecId(this.PersonalTitle);
        locAVADirNameAffixTranslation   = AVADirNameAffixTranslation::findByDirNameAffixAndLanguage(this.PersonalTitle, _languageId);
    }
    else
    {
        select firstonly locDirNameAffix
        where   locDirNameAffix.AVAGender == this.Gender
            &&  locDirNameAffix.AffixType == DirNameAffixType::PersonalPrefix;

        locAVADirNameAffixTranslation   = AVADirNameAffixTranslation::findByDirNameAffixAndLanguage(locDirNameAffix.RecId, _languageId);
    }

    if(locAVADirNameAffixTranslation.AVAAffixTxt)
    {
        retVal = locAVADirNameAffixTranslation.AVAAffixTxt;
    }
    else if(locDirNameAffix.AVAKnownAs)
    {
        retVal = locDirNameAffix.AVAKnownAs;
    }

    if(_lastNameFirst)
    {
        locAVAContactName += locDirPersonName.LastName;
        if(locDirPersonName.FirstName && locDirPersonName.LastName)
        {
            locAVAContactName += ', ';
        }
        locAVAContactName += locDirPersonName.FirstName;
    }
    else
    {
        locAVAContactName += locDirPersonName.FirstName;
        if(locDirPersonName.FirstName && locDirPersonName.LastName)
        {
            locAVAContactName += ' ';
        }
        locAVAContactName += locDirPersonName.LastName;
    }

    if(retVal && locAVAContactName)
    {
        retVal += ' ';
    }
    retVal += locAVAContactName;

    return retVal;
}
